  const panelMats = [['#7D8488', '#5c6368', 11], ['#A68966', '#7a6348', 23], ['#8EA4AE', '#667a84', 37]].map(([wc, sc, sd]) => { const [b, e] = facadeTexs(wc, sc, sd); const m = std({ map: b, emissive: 0xF4A259, emissiveMap: e, emissiveIntensity: 0, roughness: .86 }); neons.push({ material: m }); return m; });
  const roofPM = std({ color: 0x4E3D36, roughness: .8 }), doorPM = std({ color: 0x4E3D36, roughness: .7 }), canPM = std({ color: 0x7D8488, roughness: .8 });
  const panelGeo = (gw, gh, gd) => { const gg = new THREE.BoxGeometry(gw, gh, gd), uv = gg.attributes.uv; const sz = [[gd, gh], [gd, gh], [gw, gd], [gw, gd], [gw, gh], [gw, gh]];
    for (let fc = 0; fc < 6; fc++) for (let k = 0; k < 4; k++) { const ii = fc * 4 + k; uv.setXY(ii, uv.getX(ii) * sz[fc][0] / 24, uv.getY(ii) * sz[fc][1] / 11.2); } return gg; };
