        if (glow) { if (lit) { g.fillStyle = '#F4A259'; g.fillRect(x0 + 5, y0 + 5, ww - 10, wh - 10); } continue; }
        g.fillStyle = '#5c6368'; g.fillRect(x0 - 4, y0 - 6, ww + 8, 6);                      // бетонная перемычка панели
        g.fillStyle = '#E8D8C3'; g.fillRect(x0, y0, ww, wh);                                 // деревянная рама
        g.fillStyle = lit ? '#F4A259' : (c + r) % 3 === 0 ? '#3a4a56' : '#1B2A4A'; g.fillRect(x0 + 5, y0 + 5, ww - 10, wh - 10);
        if (!lit && (c * 3 + r) % 3 === 1) { g.fillStyle = 'rgba(232,216,195,.46)'; g.fillRect(x0 + 5, y0 + 5, (ww - 10) * .42, wh - 10); } // тюль за стеклом
        g.fillStyle = '#E8D8C3'; g.fillRect(x0 + ww * .62, y0, 4, wh); g.fillRect(x0 + ww * .62, y0 + wh * .32, ww * .38, 4);   // переплёт с форточкой
        g.fillStyle = '#52665A'; g.fillRect(x0 - 6, y0 + wh, ww + 12, 5);                    // стальной подоконный отлив
        g.fillStyle = 'rgba(240,244,248,.9)'; g.fillRect(x0 - 6, y0 + wh - 3, ww + 12, 3);   // снег на отливе
