  //  между лучами крестов и вспомогательные корпуса: больница, баня, мастерские, комната передач)
  // ============================================================================
  const _rlS = relocStart();
  const sizoWeatheredBrickTex = regTex(ctex(256, 256, (g, w, h) => {
    g.fillStyle = '#6e281c'; g.fillRect(0, 0, w, h);
    for (let y = 0; y < h; y += 16) {
      const off = (y / 16) % 2 ? 16 : 0;
      for (let x = -16; x < w; x += 32) {
        g.fillStyle = ((x + y) % 48 === 0) ? '#541c13' : '#782c1f';
        g.fillRect(x + off + 1, y + 1, 30, 14);
      }
    }
    // Белые солевые высолы, копоть и трещины 1992 года на старинном кирпиче
    stains(g, w, h, 24, 'rgba(220,215,205,');
    stains(g, w, h, 28, 'rgba(18,14,12,');
  }, [6, 4]));
  const sizoBrickM = std({ map: sizoWeatheredBrickTex, roughness: .90 });
  const sizoRoofM  = std({ color: 0x4e5458, roughness: .52, metalness: .55 });
  const sizoMuzzleM = std({ color: 0x262a2e, roughness: .62, metalness: .65 }); // металлические жалюзи-«реснички» («намордники»)

  // Функция постройки 5-этажного равноконечного крестообразного корпуса («Креста») с центральной башней,
  // рядами окон с металлическими «ресничками» на 5 этажах и прогулочными двориками-боксами между лучами креста
  const buildKrestBuilding = (cx, cz) => {
    // Горизонтальный и вертикальный 5-этажные лучи равноконечного креста (высота 14.5 м — 5 этажей)
    mcBox(32.0, 14.5, 7.6, sizoBrickM, cx, 7.25, cz);
    mcBox(32.6, .45,  8.2, sizoRoofM,  cx, 14.72, cz);
    addCol(cx - 16.2, cx + 16.2, cz - 3.9, cz + 3.9);

    mcBox(7.6, 14.5, 32.0, sizoBrickM, cx, 7.25, cz);
    mcBox(8.2, .45,  32.6, sizoRoofM,  cx, 14.72, cz);
    addCol(cx - 3.9, cx + 3.9, cz - 16.2, cz + 16.2);

    // Центральная восьмигранная башня-фонарь на перекрестье со световыми окнами
    mcCyl(5.2, 5.5, 16.8, sizoBrickM, cx, 8.4, cz, 8);
    mcCyl(.6,  5.8, 2.4,  sizoRoofM,  cx, 18.0, cz, 8);

    // 5 этажей маленьких тюремных окон с металлическими козырьками-«ресничками» («намордниками») вдоль лучей
    for (let fl = 0; fl < 5; fl++) {
      const wy = 1.8 + fl * 2.75;
      for (const off of [-13.5, -10.5, -7.5, 7.5, 10.5, 13.5]) {
        // На продольном крыле (южный и северный фасады)
        mcBox(.85, .55, .28, sizoMuzzleM, cx + off, wy, cz - 3.92, false);
        mcBox(.85, .55, .28, sizoMuzzleM, cx + off, wy, cz + 3.92, false);
        // На поперечном крыле (западный и восточный фасады)
        mcBox(.28, .55, .85, sizoMuzzleM, cx - 3.92, wy, cz + off, false);
        mcBox(.28, .55, .85, sizoMuzzleM, cx + 3.92, wy, cz + off, false);
      }
    }

    // Внутренние прогулочные дворики-боксы с решёткой над головой в треугольных углах между лучами креста
    for (const [sx, sz] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) {
      const yx = cx + sx * 8.2, yz = cz + sz * 8.2;
      mcBox(6.8, 3.0, .28, sizoBrickM, yx, 1.5, yz - 3.4);
      mcBox(6.8, 3.0, .28, sizoBrickM, yx, 1.5, yz + 3.4);
      mcBox(.28, 3.0, 6.8, sizoBrickM, yx - 3.4, 1.5, yz);
      mcBox(.28, 3.0, 6.8, sizoBrickM, yx + 3.4, 1.5, yz);
      mcBox(6.6, 2.8, .22, sizoBrickM, yx, 1.4, yz); // перегородка двориков-боксов
      mcBox(.22, 2.8, 6.6, sizoBrickM, yx, 1.4, yz);
      for (let gx = -2.8; gx <= 2.8; gx += .9) {
        mcBox(.04, .04, 6.6, sizoMuzzleM, yx + gx, 3.02, yz, false); // решётка над головой
      }
      addCol(yx - 3.5, yx + 3.5, yz - 3.5, yz + 3.5);
    }
  };

  // КОРПУС № 1 (Западный крест) и КОРПУС № 2 (Восточный крест)
  buildKrestBuilding(-138.0, 118.0);
