  const peredachiSignTex = textTex(512, 96, 'БЮРО ПРИЁМА ПЕРЕДАЧ И СВИДАНИЙ · ОКНА № 1–3', '#5e1612', '#f5ebd2', '900 22px Arial');
  const peredachiSign = new THREE.Mesh(new THREE.PlaneGeometry(3.8, .68), std({ map: peredachiSignTex, roughness: .5 }));
  peredachiSign.position.set(-146.0, 2.85, 87.82); peredachiSign.rotation.y = Math.PI; mapCityGroup.add(peredachiSign);
  // 2) Больничный корпус, баня, кухня и тюремные мастерские (x = -96.0, z = 91.5)
