  // ---------- объединение статической геометрии по материалам (сотни мелких мешей → десятки вызовов отрисовки) ----------
  function _hasCustomCompile(m) {
    return !!(m && m.onBeforeCompile && m.onBeforeCompile !== THREE.Material.prototype.onBeforeCompile);
  }
  function batchStatic(root) {
    root.updateMatrixWorld(true);
    const groups = new Map();
    const matPool = new Map();
    const dedup = m => {
      if (!m || Array.isArray(m) || _hasCustomCompile(m) || m.isShaderMaterial || m.transparent || m.vertexColors) return m;
      const k = [m.color ? m.color.getHex() : 0, Math.round((m.roughness ?? 0.85) * 100), Math.round((m.metalness ?? 0) * 100),
        m.emissive ? m.emissive.getHex() : 0, Math.round((m.emissiveIntensity ?? 0) * 100),
        m.map ? m.map.uuid : '', m.emissiveMap ? m.emissiveMap.uuid : '', m.normalMap ? m.normalMap.uuid : '',
        m.roughnessMap ? m.roughnessMap.uuid : '', m.side || 0].join('|');
      if (matPool.has(k)) return matPool.get(k);
      matPool.set(k, m);
      return m;
    };
    const tmpB = new THREE.Box3(), tmpC = new THREE.Vector3(), tmpS = new THREE.Vector3();
    root.traverse(o => {
      if (!o.isMesh || o.isInstancedMesh || o.userData.keep || winterGround.includes(o) || summerGround.includes(o)) return;
      for (let p = o; p; p = p.parent) if ((p.userData && p.userData.dyn) || p === K || p.visible === false) return;
      if (Array.isArray(o.material) || o.material.isShaderMaterial || o.material.transparent) return;
      o.material = dedup(o.material);
      tmpB.setFromObject(o);
      if (tmpB.isEmpty()) return;
      tmpB.getCenter(tmpC);
      tmpB.getSize(tmpS);
      const span = Math.max(tmpS.x, tmpS.z);
      if (span > 85) return;
      if (span < 1.8) o.castShadow = false;
      const cellKey = Math.floor(tmpC.x / 56) + '_' + Math.floor(tmpC.z / 56);
      const key = cellKey + '|' + o.material.uuid + '|' + (o.castShadow ? 1 : 0) + '|' + (o.userData.winter ? 1 : 0);
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push(o);
    });
    let removed = 0, added = 0;
    const geoRefCount = new Map();
    root.traverse(o => { if (o.isMesh && o.geometry) geoRefCount.set(o.geometry, (geoRefCount.get(o.geometry) || 0) + 1); });
    for (const [, list] of groups) {
      if (list.length < 2) continue;
      const geos = list.map(m => {
        let g = m.geometry.index ? m.geometry.toNonIndexed() : m.geometry.clone();
        g.clearGroups();
        for (const k of Object.keys(g.attributes)) if (!['position', 'normal', 'uv'].includes(k)) g.deleteAttribute(k);
        if (!g.attributes.normal) g.computeVertexNormals();
        if (!g.attributes.uv) g.setAttribute('uv', new THREE.Float32BufferAttribute(new Float32Array(g.attributes.position.count * 2), 2));
        g.applyMatrix4(m.matrixWorld);
        return g;
      });
      const merged = mergeGeometries(geos, false);
      geos.forEach(g => g.dispose());
      if (!merged) continue;
      const mm = new THREE.Mesh(merged, list[0].material);
      mm.castShadow = list[0].castShadow;
      mm.receiveShadow = true;
      mm.userData.winter = !!list[0].userData.winter;
      mm.updateMatrix(); mm.matrixAutoUpdate = false;
      scene.add(mm); added++;
      list.forEach(m => {
        if (m.parent) m.parent.remove(m);
        if (m.geometry) {
          const rc = (geoRefCount.get(m.geometry) || 1) - 1;
          geoRefCount.set(m.geometry, rc);
          if (rc <= 0) m.geometry.dispose();
        }
        removed++;
      });
    }
    return { removed, added };
  }
  const batchInfo = batchStatic(scene);
  // Оптимизация: отключаем ежекадровый пересчёт матриц у всей статичной геометрии города и квартиры
  scene.traverse(o => {
    if (o.isMesh && !o.userData.dyn && !o.isSkinnedMesh) {
      o.updateMatrix();
      o.matrixAutoUpdate = false;
    }
  });

