  const toLoad = [...SDS_NPC.map(n => 'npc_' + n), 'npc_x_marat', 'npc_x_zina', 'npc_x_hero', 'guitar', 'npc_x_police1', 'npc_x_police2', 'npc_x_police_w1', 'npc_x_police_w2', 'npc_police', 'npc_driver', 'paz652', 'forest_trees', 'bmw733i', 'apartment', 'busstop', 'beton', 'tree', 'bush', 'radio', 'steelworker', 'notepad', 'chair', 'chair_old', 'kreslo', 'poster', 'nodrink', 'vodka', 'cigarette', 'stew', 'gun', 'trashcan', 'rubin', 'vityaz', 'vaz2101', 'vaz2107', 'vaz2101_lod', 'vaz2107_lod'];
  const winMats = [], winU = { time: { value: 0 }, night: { value: 0 } };
