              // Определяем тип и зону удара по главному герою: 'kick' (с ноги), 'head' (в голову) или 'gut' (в живот)
              const hitZone = npcKick ? 'kick' : (Math.random() < .56 ? 'head' : 'gut');
              const kDirX = (P.x - ox) / (dP || 1), kDirZ = (P.z - oz) / (dP || 1);
