  scene.add(rovdGroup);
  const rZ = z => (z < 50 ? z + RZ : z);
  const rBox = (w, h, d, m, x, y, z, cast = true) => box(w, h, d, m, x, y, rZ(z), rovdGroup, cast);
  const rCyl = (rt_, rb, h, m, x, y, z, seg = 12) => cyl(rt_, rb, h, m, x, y, rZ(z), seg, rovdGroup);
  const rCol = (x1, x2, z1, z2, tag) => addCol(x1, x2, rZ(z1), rZ(z2), tag);

  // Материалы советского РОВД и камеры КПЗ/СИЗО 1992 года
