  rBox(16.4, .28, 17.4, rConcreteMat, -130.0, 3.94, -9.5);
  rBox(16.2, 6.4, 7.2, rBrickMat, -130.0, 7.2, -4.5); // 2-й и 3-й кирпичные этажи РОВД
  rBox(16.8, .35, 7.8, rConcreteMat, -130.0, 10.55, -4.5);
