  rBox(.32, 3.8, 17.0, rBrickMat, -122.0, 1.9, -9.5); rCol(-122.25, -121.75, -18.2, -.8);

  // НАСТОЯЩАЯ ЗАКРЫТАЯ ДВУСТВОРЧАТАЯ ДВЕРЬ УЧАСТКА МИЛИЦИИ 1992 ГОДА (в проёме x = -131.2 .. -128.8, z = -1.0 + RZ) ВМЕСТО СИНЕЙ ЛЕНТЫ!
  const rovdDoorLeatherM = std({ color: 0x3b2218, roughness: .72 });
  var rovdFrontDoorPivot = new THREE.Group();
