  const obezyannikBarsBox  = new THREE.Box3(new THREE.Vector3(-133.65, 0, -3.85 + RZ), new THREE.Vector3(-132.75, 2.50, -1.20 + RZ));
  const inObezyannik = (x = P.x, z = P.z) => x > -137.9 && x < -133.15 && z > (-3.90 + RZ) && z < (-1.10 + RZ);

