      const gdLook = makeLook('police');
      Object.assign(gdLook, { male: true, height: 1.79, build: 1.10, top: '#1e2838', pants: '#18202c', hat: 'none', bag: null, coat: false });
      const gdM = POLICE.mid[0] || policeModel; const gdH = new Human(gdLook, gdM || null);
      if (gdM && gdM.sds) dressPolice(gdH, gdM);
      gdH.obj.position.set(-129.0, 0, -9.8 + RZ);
