    const hasMurder = !!((S && S.flags && S.flags.kills > 0) || (S && S.npcMemory && S.npcMemory.crimes && S.npcMemory.crimes.kills > 0));
    const bribe = Math.max(250, Math.round(rate * 1.5));
    const reasonText = p.heardCrimeType === 'kill'
      ? 'местные жители сообщили, что неподалёку от вашего ларька уложили человека'
      : p.heardCrimeType === 'gun'
